sys_script_include.script:
var correio = Class.create();
correio.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    buscaCEP: function() {
        try {
            var cep = this.getParameter('sysparm_cep');

            var r = new sn_ws.RESTMessageV2('x_1441719_aumiau_0.Consulta CEP', 'cep');
            r.setStringParameterNoEscape('cep', cep);
            var response = r.execute();
            var responseBody = response.getBody();
            var httpStatus = response.getStatusCode();
            return responseBody;
        } catch (ex) {
            return "error";
        }
    },
    type: 'correio'
});
